def solve_test_input_v4(grid):
    bg = 9
    h, w = len(grid), len(grid[0])

    # Group by value
    cells_by_val = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg and v != 0:
                if v not in cells_by_val:
                    cells_by_val[v] = []
                cells_by_val[v].append((r, c))

    # Check connectivity
    def get_connected_cells(cells, bg_val):
        """Find connected groups within cells of same value."""
        cleaned = [(r, c) for r, c in cells if grid[r][c] != bg_val]
        if len(cleaned) <= 1:
            return cleaned

        # BFS to find connected (4-directional)
        visited = set()
        groups = []

        for start in cleaned:
            if start in visited:
                continue

            group = []
            queue = [start]
            while queue:
                r, c = queue.pop(0)
                if (r, c) in visited:
                    continue
                visited.add((r, c))
                group.append((r, c))

                for dr, dc in (-1, 0), (1, 0), (0, -1), (0, 1):
                    nr, nc = r + dr, c + dc
                    if (nr, nc) in cleaned and (nr, nc) not in visited:
                        queue.append((nr, nc))

            if group:
                groups.append(group)

        return groups

    result = [[bg for _ in range(w)] for _ in range(h)]

    for v, cells in cells_by_val.items():
        groups = get_connected_cells(cells, bg)

        for group in groups:
            # All cells in the group share at least one diagonal
            # But extend along ALL diagonals that contain any cell in the group
            main_diags = [r - c for r, c in group]
            anti_diags = [r + c for r, c in group]

            # Fill all these diagonals
            for mk in main_diags:
                for r in range(h):
                    c = r - mk
                    if 0 <= c < w and result[r][c] == bg:
                        result[r][c] = v

            for ak in anti_diags:
                for c in range(w):
                    r = ak - c
                    if 0 <= r < h and result[r][c] == bg:
                        result[r][c] = v

    return result

